//! Runs models generated by stanc-rs through the stan-model-rs [`Model`] interface.
//!
//! stanc-rs currently generates code against its own minimal runtime crate,
//! `stanc-rs-runtime`. [`Stanc`] wraps any such model so that inference code written against
//! stan-model-rs can use it, and [`generated`] holds the programs of `tests/stan/` compiled by
//! stanc-rs at build time, for the end-to-end tests. When stanc-rs generates code against
//! stan-model-rs directly, this adapter goes away.
//!
//! Errors keep the Stan source locations stanc-rs records, and `print` output reaches
//! [`stan_model_rs::print`]'s sinks (see [`forward_print`]).
//!
//! The stanc-rs runtime has no Hessian drivers and does not report constraints, so
//! [`Model::log_density_hessian`] and [`Model::log_density_hessian_vector_product`] return
//! [`ErrorKind::Unsupported`], and the metadata lists every variable as unconstrained real
//! values with its declared shape.

use std::io::Write;

use stan_model_rs::meta::{BaseType, Block, Constraint, ModelInfo, Outputs, VarInfo};
use stan_model_rs::rand::Rng;
use stan_model_rs::stanmath_rs::Matrix;
use stan_model_rs::{Data, ErrorKind, LogDensityOptions, Model, ModelError, Result};
use stanc_rs_runtime as rt;

/// The programs of `tests/stan/`, compiled by stanc-rs.
#[allow(missing_docs, clippy::all)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/models.rs"));
}

/// The stanc-rs revision the adapter is built against.
pub const COMPILER: &str = "stanc-rs 0.1.0 (02406c5)";

/// A stanc-rs model seen through the stan-model-rs interface.
pub struct Stanc<M> {
    inner: M,
    info: ModelInfo,
}

fn convert_error(e: rt::ModelError) -> ModelError {
    let kind = match e.kind {
        rt::ErrorKind::Data => ErrorKind::Data,
        rt::ErrorKind::Domain => ErrorKind::Domain,
        rt::ErrorKind::Index => ErrorKind::Index,
        rt::ErrorKind::Size => ErrorKind::Size,
        rt::ErrorKind::Reject => ErrorKind::Reject,
        rt::ErrorKind::Fatal => ErrorKind::Fatal,
        rt::ErrorKind::Parameters => ErrorKind::Parameters,
        #[allow(unreachable_patterns)]
        _ => ErrorKind::Internal,
    };
    let mut out = ModelError::new(kind, e.message);
    out.locations = e.locations;
    out
}

/// Runs `f` with the stanc-rs runtime's `print` output passed on, line by line, to
/// [`stan_model_rs::print`], so that `stan_model_rs::print::with_sink` captures what generated
/// models print. [`Stanc`] does this for every evaluation; wrap model constructors (whose
/// transformed data block may print) in it as well.
pub fn forward_print<R>(f: impl FnOnce() -> R) -> R {
    let (r, mut lines) = rt::print::with_sink(Lines(Vec::new()), f);
    lines.finish();
    r
}

/// Splits the bytes the stanc-rs runtime writes into lines.
struct Lines(Vec<u8>);

impl Lines {
    fn emit(&mut self, end: usize) {
        let line: Vec<u8> = self.0.drain(..end).collect();
        stan_model_rs::print::line(String::from_utf8_lossy(&line).trim_end_matches('\n'));
    }

    fn finish(&mut self) {
        if !self.0.is_empty() {
            self.emit(self.0.len());
        }
    }
}

impl Write for Lines {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.0.extend_from_slice(buf);
        while let Some(i) = self.0.iter().position(|&b| b == b'\n') {
            self.emit(i + 1);
        }
        Ok(buf.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn convert_var(v: &rt::VarInfo) -> VarInfo {
    let block = match v.block {
        rt::VarBlock::Parameters => Block::Parameters,
        rt::VarBlock::TransformedParameters => Block::TransformedParameters,
        rt::VarBlock::GeneratedQuantities => Block::GeneratedQuantities,
    };
    if !v.slots.is_empty() {
        let slots = v.slots.iter().map(convert_var).collect();
        return VarInfo::tuple(v.name.clone(), block, v.dims.clone(), slots);
    }
    let k = v.dims.len();
    let (array_dims, base) = match (v.matrix, v.complex) {
        (true, false) => (
            v.dims[..k - 2].to_vec(),
            BaseType::Matrix(v.dims[k - 2], v.dims[k - 1]),
        ),
        (true, true) => (
            v.dims[..k - 2].to_vec(),
            BaseType::ComplexMatrix(v.dims[k - 2], v.dims[k - 1]),
        ),
        (false, true) => (v.dims.clone(), BaseType::Complex),
        (false, false) => (v.dims.clone(), BaseType::Real),
    };
    VarInfo::new(v.name.clone(), block, array_dims, base, Constraint::None)
}

impl<M: rt::Model> Stanc<M> {
    /// Wraps a stanc-rs model.
    pub fn new(inner: M) -> Self {
        let mut info = ModelInfo::new(
            inner.name().to_string(),
            inner.variables().iter().map(convert_var).collect(),
        );
        info.compiler = Some(COMPILER.to_string());
        Stanc { inner, info }
    }

    /// The wrapped model.
    pub fn inner(&self) -> &M {
        &self.inner
    }
}

fn density_options(o: LogDensityOptions) -> rt::DensityOptions {
    rt::DensityOptions {
        jacobian: o.jacobian,
        propto: o.propto,
    }
}

/// Converts data to the stanc-rs runtime's data type.
pub fn convert_data(data: &Data) -> Result<rt::data::Data> {
    rt::data::Data::from_json_str(&data.to_json_string()).map_err(convert_error)
}

/// Nests output-order values `x` (column-major over `dims`) into JSON lists (row-major nesting,
/// matrices as lists of rows), the inverse of CmdStan's JSON reader.
fn nest(x: &[f64], dims: &[usize]) -> serde_json::Value {
    fn build(x: &[f64], dims: &[usize], idx: &mut Vec<usize>) -> serde_json::Value {
        if idx.len() == dims.len() {
            // Column-major position of the index.
            let mut p = 0;
            for (i, d) in idx.iter().zip(dims).rev() {
                p = p * d + i;
            }
            return serde_json::json!(x[p]);
        }
        let n = dims[idx.len()];
        let items = (0..n)
            .map(|i| {
                idx.push(i);
                let v = build(x, dims, idx);
                idx.pop();
                v
            })
            .collect();
        serde_json::Value::Array(items)
    }
    build(x, dims, &mut Vec::new())
}

impl<M: rt::Model> Model for Stanc<M> {
    fn info(&self) -> &ModelInfo {
        &self.info
    }

    fn num_unconstrained(&self) -> usize {
        self.inner.num_unconstrained()
    }

    fn param_names(&self, outputs: Outputs) -> Vec<String> {
        self.inner
            .param_names(outputs.transformed_parameters, outputs.generated_quantities)
    }

    fn unconstrained_param_names(&self) -> Vec<String> {
        self.inner.unconstrained_param_names()
    }

    fn num_outputs(&self, outputs: Outputs) -> usize {
        self.param_names(outputs).len()
    }

    fn log_density(&self, theta: &[f64], opts: LogDensityOptions) -> Result<f64> {
        forward_print(|| self.inner.log_density(theta, density_options(opts)))
            .map_err(convert_error)
    }

    fn log_density_gradient(
        &self,
        theta: &[f64],
        opts: LogDensityOptions,
    ) -> Result<(f64, Vec<f64>)> {
        forward_print(|| {
            self.inner
                .log_density_gradient(theta, density_options(opts))
        })
        .map_err(convert_error)
    }

    fn log_density_gradient_into(
        &self,
        theta: &[f64],
        opts: LogDensityOptions,
        gradient: &mut [f64],
    ) -> Result<f64> {
        if gradient.len() != self.num_unconstrained() {
            return Err(ModelError::parameters(format!(
                "expected {} gradient entries, found {}",
                self.num_unconstrained(),
                gradient.len()
            )));
        }
        let (v, g) = self.log_density_gradient(theta, opts)?;
        gradient.copy_from_slice(&g);
        Ok(v)
    }

    fn log_density_hessian(
        &self,
        _theta: &[f64],
        _opts: LogDensityOptions,
    ) -> Result<(f64, Vec<f64>, Matrix<f64>)> {
        Err(ModelError::new(
            ErrorKind::Unsupported,
            "stanc-rs models do not provide Hessians yet",
        ))
    }

    fn log_density_hessian_vector_product(
        &self,
        _theta: &[f64],
        _v: &[f64],
        _opts: LogDensityOptions,
    ) -> Result<Vec<f64>> {
        Err(ModelError::new(
            ErrorKind::Unsupported,
            "stanc-rs models do not provide Hessian-vector products yet",
        ))
    }

    fn write_array(&self, theta: &[f64], outputs: Outputs, rng: &mut dyn Rng) -> Result<Vec<f64>> {
        forward_print(|| {
            self.inner.write_array(
                theta,
                outputs.transformed_parameters,
                outputs.generated_quantities,
                rng,
            )
        })
        .map_err(convert_error)
    }

    fn param_unconstrain(&self, constrained: &[f64]) -> Result<Vec<f64>> {
        let n = self.num_outputs(Outputs::PARAMETERS);
        if constrained.len() != n {
            return Err(ModelError::parameters(format!(
                "expected {n} constrained parameter values, found {}",
                constrained.len()
            )));
        }
        let mut values = Data::empty();
        let mut pos = 0;
        for v in self.info.parameters() {
            if v.is_tuple() {
                return Err(ModelError::new(
                    ErrorKind::Unsupported,
                    "flat values of tuple parameters; use param_unconstrain_json",
                )
                .with_variable(v.name.clone()));
            }
            let k = v.num_constrained();
            values.insert(v.name.clone(), nest(&constrained[pos..pos + k], &v.dims()));
            pos += k;
        }
        self.param_unconstrain_json(&values)
    }

    fn param_unconstrain_json(&self, values: &Data) -> Result<Vec<f64>> {
        let values = convert_data(values)?;
        forward_print(|| self.inner.unconstrain(&values)).map_err(convert_error)
    }
}
